vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;

vec2 offset = vec2(0.25, 0.15);
float d = length(p - offset) - 0.25;

float w = fwidth(d);
float fill = 1.0 - smoothstep(-w, w, d);

vec3 colour = mix(vec3(0.05, 0.05, 0.08), vec3(0.31, 0.84, 1.0), fill);

fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;

vec2 offset = vec2(0.25, 0.15);
p = p + offset;

float d = length(p) - 0.25;

float w = fwidth(d);
float fill = 1.0 - smoothstep(-w, w, d);

vec3 colour = mix(vec3(0.05, 0.05, 0.08), vec3(0.31, 0.84, 1.0), fill);

fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;

vec2 shift = vec2(sin(iTime) * 0.2, 0.0);
vec2 q = p + shift;

float a = length(q - vec2(-0.16, 0.2)) - 0.14;
float b = length(q - vec2(0.2, -0.18)) - 0.14;
float d = min(a, b);

float w = fwidth(d);
float fill = 1.0 - smoothstep(-w, w, d);

vec3 colour = mix(vec3(0.05, 0.05, 0.08), vec3(0.78, 0.96, 0.39), fill);

fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;

vec2 camera = vec2(sin(iTime * 0.7) * 0.18, cos(iTime * 0.7) * 0.14);
vec2 q = p + camera;

float d = length(q - vec2(0.12, 0.1)) - 0.18;

float w = fwidth(d);
float fill = 1.0 - smoothstep(-w, w, d);

vec3 colour = mix(vec3(0.05, 0.05, 0.08), vec3(0.31, 0.84, 1.0), fill);

fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;

vec2 q = p * 1.6;

float rounding = 0.08;
vec2 box = abs(q) - (vec2(0.34, 0.22) - rounding);
float d = length(max(box, 0.0)) - rounding;

float w = fwidth(d);
float fill = 1.0 - smoothstep(-w, w, d);

vec3 colour = mix(vec3(0.05, 0.05, 0.08), vec3(0.78, 0.96, 0.39), fill);

fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;

float angle = 0.6;
float c = cos(angle);
float s = sin(angle);
vec2 q = mat2(c, s, -s, c) * p;

float rounding = 0.06;
vec2 box = abs(q) - (vec2(0.34, 0.2) - rounding);
float d = length(max(box, 0.0)) - rounding;

float w = fwidth(d);
float fill = 1.0 - smoothstep(-w, w, d);

vec3 colour = mix(vec3(0.05, 0.05, 0.08), vec3(0.78, 0.96, 0.39), fill);

fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;

vec2 pivot = vec2(0.22, -0.18);
float angle = iTime * 0.7;
float c = cos(angle);
float s = sin(angle);
vec2 q = mat2(c, s, -s, c) * (p - pivot);

float d = length(q - vec2(0.0, 0.24)) - 0.09;

float w = fwidth(d);
float fill = 1.0 - smoothstep(-w, w, d);

vec3 colour = mix(vec3(0.05, 0.05, 0.08), vec3(0.31, 0.84, 1.0), fill);

fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;

float angle = iTime * 0.5;
float c = cos(angle);
float s = sin(angle);

vec2 q = p;
q = q - vec2(sin(iTime * 0.9) * 0.16, 0.0);
q = mat2(c, s, -s, c) * q;
q = q * (1.4 + sin(iTime * 1.3) * 0.35);

float rounding = 0.06;
vec2 box = abs(q) - (vec2(0.3, 0.2) - rounding);
float d = length(max(box, 0.0)) - rounding;

float w = fwidth(d);
float fill = 1.0 - smoothstep(-w, w, d);

vec3 colour = mix(vec3(0.05, 0.05, 0.08), vec3(0.78, 0.96, 0.39), fill);

fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;

float r = length(p);
float a = atan(p.y, p.x);

fragColor = vec4(r, a / 6.28318 + 0.5, 0.3, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;

float a = atan(p.y, p.x);
float spokes = 0.5 + 0.5 * cos(a * 8.0);

vec3 colour = mix(vec3(0.05, 0.05, 0.08), vec3(0.99, 0.86, 0.52), spokes);

fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;

float r = length(p);
float a = atan(p.y, p.x);

float petals = 0.28 + 0.1 * cos(a * 5.0);
float d = r - petals;

float w = fwidth(d);
float fill = 1.0 - smoothstep(-w, w, d);

vec3 colour = mix(vec3(0.05, 0.05, 0.08), vec3(0.95, 0.35, 0.42), fill);

fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;

float r = length(p);
float a = atan(p.y, p.x);

float v = 0.5 + 0.5 * cos(a * 3.0 + r * 14.0 - iTime * 2.0);

vec3 colour = 0.5 + 0.5 * cos(6.28318 * (v + vec3(0.0, 0.67, 0.33)));

fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;

float v = fract(uv.x * 4.0);

fragColor = vec4(vec3(v), 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;

vec2 cell = fract(p * 3.0) - 0.5;

float d = length(cell) - 0.32;

float w = fwidth(d);
float fill = 1.0 - smoothstep(-w, w, d);

vec3 colour = mix(vec3(0.05, 0.05, 0.08), vec3(0.31, 0.84, 1.0), fill);

fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;

vec2 cell = fract(p * 3.0);

float d = length(cell - vec2(0.85, 0.5)) - 0.28;

float w = fwidth(d);
float fill = 1.0 - smoothstep(-w, w, d);

vec3 colour = mix(vec3(0.05, 0.05, 0.08), vec3(1.0, 0.45, 0.42), fill);

fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;

vec2 cell = fract(p * 3.0) - 0.5;

float d = length(cell) - (0.18 + 0.12 * sin(iTime));

float w = fwidth(d);
float fill = 1.0 - smoothstep(-w, w, d);

vec3 colour = mix(vec3(0.05, 0.05, 0.08), vec3(0.78, 0.96, 0.39), fill);

fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;

vec2 id = floor(p * 3.0);

vec3 colour = vec3(id.x, id.y, 0.0) * 0.2 + 0.6;

fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;

vec2 scaled = p * 3.0;
vec2 id = floor(scaled);
vec2 cell = fract(scaled) - 0.5;

float d = length(cell) - 0.34;

float w = fwidth(d);
float fill = 1.0 - smoothstep(-w, w, d);

vec3 tint = 0.5 + 0.5 * cos(6.28318 * ((id.x + id.y) * 0.15 + vec3(0.0, 0.67, 0.33)));
vec3 colour = mix(vec3(0.05, 0.05, 0.08), tint, fill);

fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;

vec2 scaled = p * 3.0;
vec2 id = floor(scaled);
vec2 cell = fract(scaled) - 0.5;

float phase = id.x * 0.9 + id.y * 0.6;
float radius = 0.24 + 0.12 * sin(iTime * 2.0 + phase);
float d = length(cell) - radius;

float w = fwidth(d);
float fill = 1.0 - smoothstep(-w, w, d);

vec3 colour = mix(vec3(0.05, 0.05, 0.08), vec3(0.31, 0.84, 1.0), fill);

fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;

vec2 scaled = p * 3.0;
vec2 id = floor(scaled);
vec2 cell = fract(scaled) - 0.5;

float flip = mod(id.x + id.y, 2.0);
cell.x = mix(cell.x, -cell.x, flip);

float d = length(cell - vec2(0.22, 0.0)) - 0.16;

float w = fwidth(d);
float fill = 1.0 - smoothstep(-w, w, d);

vec3 colour = mix(vec3(0.05, 0.05, 0.08), vec3(0.99, 0.86, 0.52), fill);

fragColor = vec4(colour, 1.0);
